import { useEffect } from "react";

const AGENT_3D_SRC = "https://three.ws/agent-3d/1.5.2/agent-3d.js";

/** Renders the three.ws Painted Wooden Chair 01 model. The custom element is defined once per page. */
export function PaintedWoodenChair01() {
  useEffect(() => {
    if (document.querySelector('script[data-agent-3d]')) return;
    const s = document.createElement("script");
    s.type = "module";
    s.src = AGENT_3D_SRC;
    s.crossOrigin = "anonymous";
    s.dataset.agent3d = "1";
    document.head.appendChild(s);
  }, []);

  return (
    <agent-3d
      body="https://pub-2534e921bf9c4314addcd4d8a6e98b7b.r2.dev/objects/polyhaven/glb/painted_wooden_chair_01.glb"
      mode="section"
      style={{ width: "100%", height: 420, display: "block" }}
    />
  );
}

