import { useEffect } from "react";
import * as THREE from "three";

const CLIP_URL = "https://pub-2534e921bf9c4314addcd4d8a6e98b7b.r2.dev/animations/library/generated/clips/gen-wave-big-2b3a21372d56.json";

/** Plays the three.ws "Big Wave" clip on an existing avatar object. */
export function useBigWave(avatar) {
  useEffect(() => {
    if (!avatar) return;
    let mixer;
    let raf;
    let cancelled = false;
    const clock = new THREE.Clock();

    // A deadline as well as the cancelled flag: the flag stops a late response
    // touching an unmounted component, but only the signal ends a request that
    // never answers at all.
    fetch(CLIP_URL, { signal: AbortSignal.timeout(10000) })
      .then((r) => r.json())
      .then((json) => {
        if (cancelled) return;
        mixer = new THREE.AnimationMixer(avatar);
        const action = mixer.clipAction(THREE.AnimationClip.parse(json));
        action.setLoop(THREE.LoopOnce, 1);
        action.play();
        const tick = () => {
          mixer.update(clock.getDelta());
          raf = requestAnimationFrame(tick);
        };
        tick();
      });

    return () => {
      cancelled = true;
      if (raf) cancelAnimationFrame(raf);
      mixer?.stopAllAction();
    };
  }, [avatar]);
}
